use std::io
use std::collections::HashMap

fn main() {
    let text = io.read_to_string() ?? ""
    let mut first = true
    let mut k = 0
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut cur = ""
    for line in text.lines() {
        if first {
            first = false
            k = line.trim().parse::<int>().unwrap_or(0)
            continue
        }
        for c in line.chars() {
            if c.is_ascii_alphanumeric() {
                cur = cur + c.to_ascii_lowercase().to_string()
            } else if cur.len() > 0 {
                let n = counts.get(cur).unwrap_or(0)
                counts.insert(cur, n + 1)
                cur = ""
            }
        }
        if cur.len() > 0 {
            let n = counts.get(cur).unwrap_or(0)
            counts.insert(cur, n + 1)
            cur = ""
        }
    }
    let mut items: Vec<(string, int)> = Vec::new()
    for (w, c) in counts {
        items.push((w, c))
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(a.1)
        } else {
            a.0.cmp(b.0)
        }
    })
    let mut i = 0
    while i < items.len() && i < k {
        println("${items[i].0} ${items[i].1}")
        i += 1
    }
}

